// Casos de prueba del motor propio: cada frase con lo que la pantalla «Lo que entendí» debe decir.
// CASOS_REVISION: cada frase que señaló la revisión de la fase 1b (negaciones, salario, lugares, papeles…).
// CASOS_VARIADOS: instrucciones dominicanas de todo tipo: ventas y empleos, con jerga, errores, MAYÚSCULAS,
// emojis e inglés.
// CASOS_EQUIPO_ROJO: cada frase con la que la primera ronda del equipo rojo hizo que «Lo que entendí» dijera algo
// falso o no preguntara (y otras parecidas que salieron al arreglarlas). Lo que no se nombra en «espera» debe quedar vacío (sin sectores, sin zonas, etc.).
// CASOS_EQUIPO_ROJO_2: lo mismo para la segunda tanda de la ronda 1 (tamaños de un solo negocio, la tienda o la web del dueño,
// suplidores y clientes que ya tiene, enlaces, horarios, salarios por quincena, lugares con su provincia, exclusiones en inglés,
// prioridades que también son negocios, frecuencias que no existen, llamar o WhatsApp, «sin preguntarme»…).
// CASOS_EQUIPO_ROJO_3: lo mismo para la segunda ronda (el negocio propio, direcciones web sin «www», clientes que ya tiene sin
// nombre, horarios, «usa» como verbo, partes de un lugar, listas de más de 30, cada negocio con su producto, inglés, y textos
// que terminan en «no» sin punto, que hacían fallar el motor).
// CASOS_EQUIPO_ROJO_4: lo mismo para la tercera ronda (lo que vende o hace otra persona, la competencia nombrada, dónde no entrega,
// cada producto con su negocio, «la prioridad son…», clientes con nombre en cualquier orden, dónde trabajó o estudió antes, salarios
// en letras o con excepciones, el periodo de pago después del salario, teletrabajo, lugares de los que no está seguro, «Sabana
// Grande», la frontera, frecuencias que se saltan días, personas sueltas, su propio Instagram, la risa al final, inglés…), y frases
// parecidas para que el arreglo sea general y no rompa lo que ya funcionaba.
// «dudas» son las preguntas que bloquean la aprobación; «faltantes», los datos que faltan.
// Este archivo no es una prueba: lo usa test/motor.test.js.

